# /srv/jwteam_clone/shared/run_current/workspace/audit.py

"""
实现概要：
- _SUPPORTED_EVENT_TYPES: 5 种事件类型
- _REQUIRED_FIELDS: 每种事件的必填字段集合
- _AUDIT_HMAC_KEY: 从环境变量 AUDIT_HMAC_KEY 读取，默认 'default-key'
- _compute_signature(entry): HMAC-SHA256 hex，排除 signature，字母序排序
- _compute_checksum(entry): SHA-256 hex，排除 signature 和 checksum
- _compute_prev_hash(): 前一条 entry 的 SHA-256 hex，首条为 ""
- log_event(): 验证 → 自动补 timestamp → 生成 log_id/prev_hash/checksum → 签名 → 存储
- verify_log(): hmac.compare_digest 常量时间比较，缺失 signature 或签名不匹配 → 索引列表
"""

import uuid, hashlib, hmac, json, os
from datetime import datetime, timezone
from typing import Any

_SUPPORTED_EVENT_TYPES = {"config_changed","user_login","report_accessed","data_exported","payment_initiated"}
_REQUIRED_FIELDS = {
    "config_changed": {"user_id","timestamp","config_key","old_value","new_value","user_agent"},
    "user_login": {"user_id","timestamp","ip_address","success","correlation_id"},
    "report_accessed": {"user_id","timestamp","report_id","report_type","request_id"},
    "data_exported": {"user_id","timestamp","export_format","record_count","destination","user_agent"},
    "payment_initiated": {"user_id","timestamp","amount","currency","recipient_account","session_id"},
}
_AUDIT_HMAC_KEY = os.environ.get("AUDIT_HMAC_KEY", "default-key")
_AUDIT_LOG = []

def _canonical_json(data): return json.dumps(data, sort_keys=True, separators=(",",":"))
def _compute_signature(entry):
    data = {k:v for k,v in entry.items() if k!="signature"}
    return hmac.new(_AUDIT_HMAC_KEY.encode(), _canonical_json(data).encode(), hashlib.sha256).hexdigest()
def _compute_checksum(entry):
    data = {k:v for k,v in entry.items() if k not in ("signature","checksum")}
    return hashlib.sha256(_canonical_json(data).encode()).hexdigest()
def _compute_prev_hash():
    if not _AUDIT_LOG: return ""
    data = {k:v for k,v in _AUDIT_LOG[-1].items() if k not in ("signature","prev_hash")}
    return hashlib.sha256(_canonical_json(data).encode()).hexdigest()

def log_event(event_type, **fields):
    if event_type not in _SUPPORTED_EVENT_TYPES:
        raise ValueError(f"Unknown event type: '{event_type}'")
    missing = _REQUIRED_FIELDS[event_type] - set(fields.keys())
    if missing: raise ValueError(f"Missing required fields for '{event_type}': {sorted(missing)}")
    if "timestamp" not in fields or fields["timestamp"] is None:
        fields["timestamp"] = datetime.now(timezone.utc).isoformat()
    entry = {"event_type": event_type, "log_id": str(uuid.uuid4())}
    entry.update(fields)
    entry["prev_hash"] = _compute_prev_hash()
    entry["checksum"] = _compute_checksum(entry)
    entry["signature"] = _compute_signature(entry)
    _AUDIT_LOG.append(entry)
    return entry

def get_log(): return list(_AUDIT_LOG)

def verify_log(entries):
    tampered = []
    for i, e in enumerate(entries):
        if "signature" not in e: tampered.append(i); continue
        if not hmac.compare_digest(_compute_signature(e), e.get("signature") or ""):
            tampered.append(i)
    return tampered
```

